<script setup>
import { computed, ref, watch } from 'vue';
import { api } from '../../services/api';
import SvgIcon from '../SvgIcon.vue';
const props = defineProps({ projectId: String, state: Object, episodeId: String, episodes: Array });
const emit = defineEmits(['refresh', 'error', 'select-episode']);
const episode = ref(null); const shots = ref([]); const selectedId = ref(''); const busy = ref(false); const links = ref([]); const quality = ref(null);
const selected = computed(() => shots.value.find(s => s.id === selectedId.value));
async function load() { if (!props.episodeId) return; try { episode.value = await api.getEpisode(props.episodeId); shots.value = episode.value.shots; if (!selectedId.value || !shots.value.some(s => s.id === selectedId.value)) selectedId.value = shots.value[0]?.id || ''; await loadLinks(); } catch(e) { emit('error', e.message); } }
async function loadLinks() { links.value = selectedId.value ? await api.getShotLinks(selectedId.value) : []; }
watch(() => props.episodeId, load, { immediate: true }); watch(selectedId, loadLinks);
async function generate() { busy.value = true; try { await api.generateStage(props.projectId, 6, props.episodeId); selectedId.value = ''; await load(); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function save() { if (!selected.value) return; try { await api.updateShotProduction(selected.value.id, selected.value); await load(); } catch(e) { emit('error', e.message); throw e; } }
async function duplicate() { if (!selected.value) return; await api.duplicateShot(selected.value.id); await load(); }
async function move(direction) { const index = shots.value.findIndex(s => s.id === selectedId.value); const target = index + direction; if (target < 0 || target >= shots.value.length) return; const ids = shots.value.map(s => s.id); [ids[index], ids[target]] = [ids[target], ids[index]]; await api.reorderShots(props.episodeId, ids); await load(); }
async function autoLink() { await api.linkEntities(props.episodeId); await loadLinks(); }
async function checkQuality() { quality.value = await api.storyboardQuality(props.episodeId); }
defineExpose({ save });
</script>
<template>
  <div>
    <div class="storyboard-toolbar"><select :value="episodeId" @change="emit('select-episode', $event.target.value)"><option v-for="e in episodes" :key="e.id" :value="e.id">第 {{ e.episode_number }} 集 · {{ e.title }}</option></select><div><button class="btn secondary small" :disabled="!shots.length" @click="autoLink">重新关联资产</button><button class="btn secondary small" :disabled="!shots.length" @click="checkQuality">分镜检查</button><button class="btn primary small" :disabled="busy || !episodeId" @click="generate"><SvgIcon name="spark" :size="15" />{{ busy ? 'AI 分镜中…' : shots.length ? '重新生成分镜' : '从剧本生成分镜' }}</button></div></div>
    <div v-if="quality" class="quality-box"><strong>{{ quality.summary }}</strong><span v-for="(issue, i) in quality.issues" :key="i">{{ issue.location }}：{{ issue.issue }}</span></div>
    <section v-if="!shots.length" class="empty-content"><SvgIcon name="grid" :size="29" /><h3>本集还没有分镜</h3><p>已审批剧本会转换为镜头列表，每个镜头都可以独立编辑、排序和复制。</p><button class="btn primary" :disabled="busy" @click="generate">生成 AI 分镜</button></section>
    <div v-else class="storyboard-workspace">
      <section class="shot-list"><div class="shot-list-head"><span>镜头列表</span><strong>{{ shots.length }} 镜 · {{ shots.reduce((n, s) => n + s.duration, 0) }} 秒</strong></div><button v-for="shot in shots" :key="shot.id" :class="{ active: selectedId === shot.id }" class="shot-list-item" @click="selectedId = shot.id"><span class="shot-index">{{ String(shot.shot_index).padStart(2, '0') }}</span><span><strong>{{ shot.scene || '未命名场景' }}</strong><small>{{ shot.camera }} · {{ shot.duration }} 秒</small><p>{{ shot.action }}</p></span><i v-if="shot.production_outdated" title="需要复核"></i></button></section>
      <section v-if="selected" class="shot-detail"><div class="detail-heading"><div><span>SHOT {{ String(selected.shot_index).padStart(2, '0') }}</span><h3>镜头详情</h3></div><div><button class="icon-btn" title="上移" @click="move(-1)">↑</button><button class="icon-btn" title="下移" @click="move(1)">↓</button><button class="btn secondary small" @click="duplicate">复制镜头</button></div></div><div class="detail-form"><div class="form-grid"><label>场景描述<input v-model="selected.scene" /></label><label>景别 / 角度<select v-model="selected.camera"><option>wide shot</option><option>medium shot</option><option>close-up</option><option>low angle</option><option>high angle</option></select></label></div><div class="form-grid"><label>预计时长（秒）<input type="number" v-model.number="selected.duration" /></label><label>出场角色<input :value="selected.characters.join('、')" @change="selected.characters = $event.target.value.split(/[、,，]/).filter(Boolean)" /></label></div><label>人物动作与画面<textarea v-model="selected.action"></textarea></label><label>对白<textarea v-model="selected.dialogue"></textarea></label><label>英文视觉提示词<textarea v-model="selected.visual_prompt" class="prompt-input"></textarea></label><div class="reference-preview"><span>关联资产参考</span><div v-if="!links.length" class="muted">暂无关联，请点击“重新关联资产”。</div><div v-for="link in links" :key="link.id" class="reference-item"><img v-if="link.reference_asset_id" :src="api.assetFileUrl(link.reference_asset_id)" /><div><strong>{{ link.mention_text }} → {{ link.entity_name || '未关联' }}</strong><small>{{ link.entity_type === 'character' ? '角色' : '场景' }} · {{ link.status }}</small></div></div></div><div class="detail-actions"><span>保存只修改当前镜头，并保留已有图像历史。</span><button class="btn primary small" @click="save">保存当前镜头</button></div></div></section>
    </div>
  </div>
</template>
<style scoped>
.storyboard-toolbar{display:flex;justify-content:space-between;gap:12px;margin-bottom:14px}.storyboard-toolbar>div{display:flex;gap:7px;flex-wrap:wrap}.storyboard-toolbar select{min-width:240px}.quality-box{display:flex;flex-direction:column;gap:4px;background:#fff7e8;border:1px solid #eed9ac;padding:12px 14px;border-radius:9px;font-size:12px;margin-bottom:14px}.empty-content{text-align:center;padding:110px 20px;background:var(--surface);border:1px dashed var(--border-strong);border-radius:12px;color:var(--text-secondary)}.empty-content h3{color:var(--text)}.storyboard-workspace{display:grid;grid-template-columns:330px 1fr;gap:14px}.shot-list,.shot-detail{background:var(--surface);border:1px solid var(--border);border-radius:11px;overflow:hidden}.shot-list{max-height:700px;overflow:auto}.shot-list-head{position:sticky;top:0;background:var(--surface);z-index:1;display:flex;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--border);font-size:12px}.shot-list-head strong{color:var(--text-secondary)}.shot-list-item{position:relative;display:grid;grid-template-columns:36px 1fr;gap:10px;width:100%;text-align:left;background:transparent;color:var(--text);border-radius:0;border-bottom:1px solid var(--border-light);padding:13px 15px}.shot-list-item.active{background:var(--accent-soft);box-shadow:inset 2px 0 var(--accent)}.shot-index{color:var(--text-tertiary);font-weight:650}.shot-list-item strong,.shot-list-item small{display:block}.shot-list-item strong{font-size:13px}.shot-list-item small{font-size:11px;color:var(--text-secondary);margin-top:3px}.shot-list-item p{font-size:11px;color:var(--text-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px;margin:7px 0 0}.shot-list-item i{position:absolute;right:10px;top:10px;width:6px;height:6px;background:#d97706;border-radius:50%}.detail-heading{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid var(--border)}.detail-heading>div{display:flex;gap:6px;align-items:center}.detail-heading span{font-size:10px;letter-spacing:1.4px;color:var(--accent);font-weight:700}.detail-heading h3{font-size:16px;margin:3px 0}.detail-heading>div:first-child{display:block}.detail-form{padding:18px}.detail-form label{display:block;font-size:12px;font-weight:600;margin:11px 0}.detail-form input,.detail-form textarea,.detail-form select{width:100%;margin-top:6px}.detail-form textarea{min-height:70px}.detail-form .prompt-input{min-height:130px;font:12px/1.7 var(--font)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.reference-preview{border-top:1px solid var(--border);padding-top:14px;margin-top:16px}.reference-preview>span{font-size:12px;font-weight:650}.reference-item{display:flex;gap:9px;align-items:center;margin-top:10px}.reference-item img{width:48px;height:48px;object-fit:cover;border-radius:7px}.reference-item strong,.reference-item small{display:block;font-size:12px}.reference-item small{color:var(--text-secondary);margin-top:4px}.detail-actions{display:flex;justify-content:space-between;align-items:center;margin-top:16px}.detail-actions span{font-size:11px;color:var(--text-secondary)}@media(max-width:900px){.storyboard-workspace{grid-template-columns:1fr}.shot-list{max-height:300px}.storyboard-toolbar{flex-direction:column}}@media(max-width:550px){.form-grid{grid-template-columns:1fr}}
</style>
